script:
async function initEditor() {
  const editPostWrapper = document.getElementById("edit-post-wrapper");
  if (editPostWrapper) {
    editPostWrapper.style.display = "none";
  }

  const loadingEl = document.createElement("div");
  loadingEl.id = "editor-loading";
  loadingEl.style.cssText =
    "display:flex; justify-content:center; height:100vh; margin-top: 25%";
  loadingEl.innerHTML = `<svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#9ca3af" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="animation:editor-spin 0.8s linear infinite"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>`;

  if (!document.getElementById("editor-loading-css")) {
    const s = document.createElement("style");
    s.id = "editor-loading-css";
    s.innerHTML = "@keyframes editor-spin{to{transform:rotate(360deg)}}";
    document.head.appendChild(s);
  }

  if (editPostWrapper) {
    editPostWrapper.parentNode.insertBefore(loadingEl, editPostWrapper);
  }

  // Load Tiptap and extensions, reload page on failure
  const modules = await Promise.all([
    import("https://esm.sh/@tiptap/core@2.2.4"),
    import("https://esm.sh/@tiptap/extension-placeholder@2.2.4"),
    import("https://esm.sh/@tiptap/starter-kit@2.2.4"),
    import("https://esm.sh/@tiptap/extension-link@2.2.4"),
    import("https://esm.sh/@tiptap/extension-text-align@2.2.4"),
    import("https://esm.sh/@tiptap/extension-image@2.2.4"),
    import("https://esm.sh/@tiptap/extension-task-list@2.2.4"),
    import("https://esm.sh/@tiptap/extension-task-item@2.2.4"),
    import("https://esm.sh/@tiptap/extension-color@2.2.4"),
    import("https://esm.sh/@tiptap/extension-text-style@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table-row@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table-cell@2.2.4"),
    import("https://esm.sh/@tiptap/extension-table-header@2.2.4"),
  ]).catch((err) => {
    console.error("Error loading Tiptap extensions:", err);
    const wrapper = document.getElementById("edit-post-wrapper");

    wrapper.innerHTML = "";
    const msg = document.createElement("p");
    msg.textContent =
      "Failed to load the editor. Please try reloading the page.";
    msg.style.cssText = "margin-bottom: 12px; color: #6b7280; font-size: 14px;";
    const btn = document.createElement("button");
    btn.textContent = "Reload";
    btn.style.cssText =
      "background-color: #1a1a1a; color: #fff; border: none; border-radius: 8px; padding: 4px 10px; font-size: 14px; cursor: pointer;";
    btn.addEventListener("click", () => window.location.reload());
    wrapper.style.alignItems = "center";
    wrapper.style.marginTop = "120px";
    wrapper.appendChild(msg);
    wrapper.appendChild(btn);
    wrapper.style.display = "flex";
    document.getElementById("editor-loading")?.remove();
    return null;
  });

  if (!modules) return;

  const [
    { Editor, mergeAttributes, Node },
    { Placeholder },
    { default: StarterKit },
    { Link },
    { TextAlign },
    { Image },
    { TaskList },
    { TaskItem },
    { Color },
    { TextStyle },
    { Table },
    { TableRow },
    { TableCell },
    { TableHeader },
  ] = modules;

  function fileToBase64(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === "string") resolve(reader.result);
        else reject(new Error("Unexpected FileReader result type"));
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  const searchParams = new URLSearchParams(window.location.search);
  const postId = searchParams.get("post-id");
  const isNewPost = !postId;

  // Number of empty paragraphs appended to give breathing room at the bottom
  // of the editor. These are stripped out before saving.
  const BOTTOM_SPACE_PARAGRAPHS = 3;

  function withBottomSpace(html) {
    return (html || "") + "<p></p>".repeat(BOTTOM_SPACE_PARAGRAPHS);
  }

  function stripTrailingEmptyParagraphs(html) {
    return (html || "").replace(
      /(?:\s*<p>(?:\s|<br\s*\/?>|&nbsp;)*<\/p>)+\s*$/i,
      "",
    );
  }

  const uploadMap = new Map();

  function generateUploadId() {
    return `upload-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  }

  function updateNodeInView(view, nodeType, uploadId, newAttrs) {
    view.state.doc.descendants((node, pos) => {
      if (node.type.name === nodeType && node.attrs.uploadId === uploadId) {
        view.dispatch(
          view.state.tr.setNodeMarkup(pos, undefined, {
            ...node.attrs,
            ...newAttrs,
          }),
        );
        return false;
      }
    });
  }

  async function retryMediaUpload(view, nodeType, uploadId, file) {
    updateNodeInView(view, nodeType, uploadId, { loading: true, error: null });
    try {
      const result = await frappeClient.uploadFile(file, {
        doctype: "Cafe Post",
        docname: postId,
        fieldname: "content",
      });
      updateNodeInView(view, nodeType, uploadId, {
        src: result.file_url,
        loading: false,
        error: null,
      });
      uploadMap.delete(uploadId);
    } catch (error) {
      updateNodeInView(view, nodeType, uploadId, {
        loading: false,
        error: error.message || `Failed to upload ${nodeType}`,
      });
      // Keep uploadMap entry so the user can click to retry again
    }
  }

  function getVideoDimensions(src) {
    return new Promise((resolve, reject) => {
      const video = document.createElement("video");
      video.preload = "metadata";
      video.onloadedmetadata = () => {
        resolve({ width: video.videoWidth, height: video.videoHeight });
        video.src = "";
      };
      video.onerror = reject;
      video.src = src;
    });
  }

  async function uploadAndInsertMedia(file, type, view, pos = null) {
    const uploadId = generateUploadId();
    let previewSrc;
    let extraAttrs = {};
    let objectUrl = null;

    if (type === "image") {
      previewSrc = await fileToBase64(file);
    } else {
      objectUrl = URL.createObjectURL(file);
      const dimensions = await getVideoDimensions(objectUrl).catch(() => ({
        width: null,
        height: null,
      }));
      previewSrc = objectUrl;
      extraAttrs = { width: dimensions.width, height: dimensions.height };
    }

    uploadMap.set(uploadId, { file });
    const insertPos = pos != null ? pos : view.state.tr.selection.from;
    const node = view.state.schema.nodes[type].create({
      src: previewSrc,
      uploadId,
      loading: true,
      ...extraAttrs,
    });
    view.dispatch(view.state.tr.insert(insertPos, node));

    try {
      const result = await frappeClient.uploadFile(file, {
        doctype: "Cafe Post",
        docname: postId,
        fieldname: "content",
      });
      if (objectUrl) URL.revokeObjectURL(objectUrl);
      updateNodeInView(view, type, uploadId, {
        src: result.file_url,
        loading: false,
      });
      uploadMap.delete(uploadId);
    } catch (error) {
      if (objectUrl) URL.revokeObjectURL(objectUrl);
      updateNodeInView(view, type, uploadId, {
        loading: false,
        error: error.message || `Failed to upload ${type}`,
      });
      // Keep uploadMap entry so retry click handler can access the file
    }
  }

  const SHARED_MEDIA_ATTRS = {
    src: { default: null },
    alt: { default: null },
    title: { default: null },
    width: { default: null },
    height: { default: null },
    uploadId: { default: null },
    loading: { default: false },
    error: { default: null },
  };

  function buildUploadDataAttrs({ uploadId, loading, error }) {
    const attrs = {};
    if (uploadId) attrs["data-upload-id"] = uploadId;
    if (loading) attrs["data-loading"] = "true";
    if (error) attrs["data-error"] = error;
    return attrs;
  }

  const CustomImage = Image.extend({
    addAttributes() {
      return { ...SHARED_MEDIA_ATTRS };
    },
    renderHTML({ HTMLAttributes }) {
      const { uploadId, loading, error, ...rest } = HTMLAttributes;
      return [
        "img",
        mergeAttributes(
          this.options.HTMLAttributes || {},
          rest,
          buildUploadDataAttrs({ uploadId, loading, error }),
        ),
      ];
    },
  });

  const CustomVideo = Node.create({
    name: "video",
    group: "block",
    selectable: true,
    draggable: true,
    atom: true,

    addAttributes() {
      return {
        ...SHARED_MEDIA_ATTRS,
        autoplay: { default: false },
        loop: { default: false },
        muted: { default: false },
      };
    },

    parseHTML() {
      return [
        {
          tag: "video",
          getAttrs: (node) => {
            if (typeof node === "string") return {};
            return {
              src: node.getAttribute("src"),
              alt: node.getAttribute("alt"),
              title: node.getAttribute("title"),
              width: node.getAttribute("width"),
              height: node.getAttribute("height"),
              autoplay: node.hasAttribute("autoplay"),
              loop: node.hasAttribute("loop"),
              muted: node.hasAttribute("muted"),
            };
          },
        },
      ];
    },

    renderHTML({ HTMLAttributes }) {
      const { uploadId, loading, error, ...rest } = HTMLAttributes;
      return [
        "video",
        mergeAttributes(
          this.options.HTMLAttributes || {},
          rest,
          buildUploadDataAttrs({ uploadId, loading, error }),
          { controls: "" },
        ),
      ];
    },
  });

  const editorElement = document.getElementById("editor");
  if (!editorElement) return;

  if (!document.getElementById("tiptap-placeholder-css")) {
    const style = document.createElement("style");
    style.id = "tiptap-placeholder-css";
    style.innerHTML = `
      .tiptap p.is-editor-empty:first-child::before {
        color: #999;
        content: attr(data-placeholder);
        float: left;
        height: 0;
        pointer-events: none;
      }
    `;
    document.head.appendChild(style);
  }

  editPostWrapper.insertAdjacentHTML("beforebegin", toolbarHTML);

  const toolbar = document.getElementById("editor-toolbar");
  if (toolbar) {
    const updateToolbarScrollFade = () => {
      const { scrollLeft, scrollWidth, clientWidth } = toolbar;
      if (scrollWidth <= clientWidth) {
        toolbar.style.maskImage = "none";
        toolbar.style.webkitMaskImage = "none";
        return;
      }
      const atStart = scrollLeft <= 0;
      const atEnd = Math.ceil(scrollLeft + clientWidth) >= scrollWidth - 1;
      let mask = "none";
      if (atStart && !atEnd) {
        mask =
          "linear-gradient(to right, black, black calc(100% - 50px), transparent)";
      } else if (!atStart && atEnd) {
        mask = "linear-gradient(to right, transparent, black 50px, black)";
      } else if (!atStart && !atEnd) {
        mask =
          "linear-gradient(to right, transparent, black 50px, black calc(100% - 50px), transparent)";
      }
      toolbar.style.maskImage = mask;
      toolbar.style.webkitMaskImage = mask;
    };
    toolbar.addEventListener("scroll", updateToolbarScrollFade, {
      passive: true,
    });
    window.addEventListener("resize", updateToolbarScrollFade);
    setTimeout(updateToolbarScrollFade, 100);
  }

  let btns = document.querySelectorAll(".tb-btn");

  const ACTIVE_CHECKS = {
    bold: (e) => e.isActive("bold"),
    italic: (e) => e.isActive("italic"),
    strike: (e) => e.isActive("strike"),
    p: (e) => e.isActive("paragraph"),
    bulletList: (e) => e.isActive("bulletList"),
    orderedList: (e) => e.isActive("orderedList"),
    taskList: (e) => e.isActive("taskList"),
    blockquote: (e) => e.isActive("blockquote"),
    code: (e) => e.isActive("code"),
    link: (e) => e.isActive("link"),
    h1: (e) => e.isActive("heading", { level: 1 }),
    h2: (e) => e.isActive("heading", { level: 2 }),
    h3: (e) => e.isActive("heading", { level: 3 }),
    h4: (e) => e.isActive("heading", { level: 4 }),
    h5: (e) => e.isActive("heading", { level: 5 }),
    h6: (e) => e.isActive("heading", { level: 6 }),
    alignLeft: (e) => e.isActive({ textAlign: "left" }),
    alignCenter: (e) => e.isActive({ textAlign: "center" }),
    alignRight: (e) => e.isActive({ textAlign: "right" }),
  };

  const editor = new Editor({
    element: editorElement,
    extensions: [
      StarterKit,
      Placeholder.configure({ placeholder: "Write your story..." }),
      Link,
      TextAlign.configure({ types: ["heading", "paragraph"] }),
      CustomImage,
      CustomVideo,
      TaskList,
      TaskItem,
      TextStyle,
      Color,
      Table.configure({ resizable: true }),
      TableRow,
      TableHeader,
      TableCell,
    ],
    editorProps: {
      attributes: {
        class:
          "prose prose-sm sm:prose lg:prose-lg xl:prose-2xl mx-auto focus:outline-none",
        style: "min-height: 85%; border: 0; outline: none;",
      },
      handleDOMEvents: {
        drop(view, event) {
          const hasFiles = event.dataTransfer?.files?.length;
          if (!hasFiles) return false;

          const files = Array.from(event.dataTransfer.files);
          const images = files.filter((f) => f.type.startsWith("image/"));
          const videos = files.filter((f) => f.type.startsWith("video/"));
          if (images.length === 0 && videos.length === 0) return false;

          event.preventDefault();
          const coordinates = view.posAtCoords({
            left: event.clientX,
            top: event.clientY,
          });
          const pos = coordinates ? coordinates.pos : view.state.selection.from;
          images.forEach((file) =>
            uploadAndInsertMedia(file, "image", view, pos),
          );
          videos.forEach((file) =>
            uploadAndInsertMedia(file, "video", view, pos),
          );
          return true;
        },
        paste(view, event) {
          const items = event.clipboardData?.items;
          if (!items) return false;

          const images = [];
          const videos = [];
          for (const item of items) {
            if (item.kind !== "file") continue;
            const file = item.getAsFile();
            if (!file) continue;
            if (item.type.startsWith("image/")) images.push(file);
            else if (item.type.startsWith("video/")) videos.push(file);
          }

          if (images.length === 0 && videos.length === 0) return false;
          event.preventDefault();
          images.forEach((file) => uploadAndInsertMedia(file, "image", view));
          videos.forEach((file) => uploadAndInsertMedia(file, "video", view));
          return true;
        },
        click(view, event) {
          const target = event.target;
          const isFailedMedia =
            (target.tagName === "IMG" || target.tagName === "VIDEO") &&
            target.dataset.error;
          if (!isFailedMedia) return false;

          const nodeType = target.tagName === "IMG" ? "image" : "video";
          const uploadId = target.dataset.uploadId;
          const fileData = uploadMap.get(uploadId);
          if (!fileData) return false;

          event.preventDefault();
          retryMediaUpload(view, nodeType, uploadId, fileData.file);
          return true;
        },
      },
    },
    onCreate: () => {
      document.getElementById("editor-loading")?.remove();
      if (editPostWrapper) editPostWrapper.style.display = "";
    },
    onTransaction: ({ editor }) => {
      btns.forEach((btn) => {
        const check = ACTIVE_CHECKS[btn.dataset.action];
        btn.classList.toggle("is-active", check ? check(editor) : false);
      });
    },
  });

  const headingBtn = document.getElementById("heading-btn");
  // const headingMenu = document.getElementById("heading-menu");
  const headingDropdown = document.createElement("div");
  headingDropdown.classList.add("cafe-dropdown");
  headingDropdown.id = "heading-menu";
  headingDropdown.innerHTML = `
          <div class="tb-dropdown-menu" id="heading-menu">
            <button class="tb-btn cafe-dropdown-item" data-action="h1">H1</button>
            <button class="tb-btn cafe-dropdown-item" data-action="h2">H2</button>
            <button class="tb-btn cafe-dropdown-item" data-action="h3">H3</button>
            <button class="tb-btn cafe-dropdown-item" data-action="h4">H4</button>
            <button class="tb-btn cafe-dropdown-item" data-action="h5">H5</button>
            <button class="tb-btn cafe-dropdown-item" data-action="h6">H6</button>
          </div>
    `;

  window.setupDropdown(headingBtn, headingDropdown);
  btns = document.querySelectorAll(".tb-btn");

  const tableBtn = document.getElementById("table-btn");
  // const tableMenu = document.getElementById("table-menu");
  const tableDropdown = document.createElement("div");
  tableDropdown.classList.add("cafe-dropdown");
  tableDropdown.id = "table-menu";
  tableDropdown.innerHTML = `
          <div class="tb-dropdown-menu" id="table-menu">
            <button class="tb-btn cafe-dropdown-item" data-action="insertTable">Insert Table</button>
            <button class="tb-btn cafe-dropdown-item" data-action="addColumnBefore">Add Column Before</button>
            <button class="tb-btn cafe-dropdown-item" data-action="addColumnAfter">Add Column After</button>
            <button class="tb-btn cafe-dropdown-item" data-action="deleteColumn">Delete Column</button>
            <button class="tb-btn cafe-dropdown-item" data-action="addRowBefore">Add Row Before</button>
            <button class="tb-btn cafe-dropdown-item" data-action="addRowAfter">Add Row After</button>
            <button class="tb-btn cafe-dropdown-item" data-action="deleteRow">Delete Row</button>
            <button class="tb-btn cafe-dropdown-item" data-action="mergeCells">Merge Cells</button>
            <button class="tb-btn cafe-dropdown-item" data-action="splitCell">Split Cell</button>
            <button class="tb-btn cafe-dropdown-item" data-action="toggleHeaderColumn">Toggle Header Column</button>
            <button class="tb-btn cafe-dropdown-item" data-action="toggleHeaderRow">Toggle Header Row</button>
            <button class="tb-btn cafe-dropdown-item" data-action="toggleHeaderCell">Toggle Header Cell</button>
            <button class="tb-btn cafe-dropdown-item" data-action="deleteTable">Delete Table</button>
          </div>
    `;
  window.setupDropdown(tableBtn, tableDropdown);

  if (tableDropdown) {
    tableDropdown.querySelectorAll("button").forEach((btn) => {
      btn.addEventListener("click", (e) => {
        e.preventDefault();
        const action = btn.dataset.action;
        if (action === "insertTable") {
          editor
            .chain()
            .focus()
            .insertTable({ rows: 3, cols: 3, withHeaderRow: true })
            .run();
        } else {
          editor.chain().focus()[action]?.().run();
        }
        tableDropdown.classList.remove("is-open");
      });
    });
  }

  btns.forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      const action = btn.dataset.action;

      const hMatch = action?.match(/^h([1-6])$/);
      if (hMatch) {
        editor
          .chain()
          .focus()
          .toggleHeading({ level: parseInt(hMatch[1], 10) })
          .run();
        headingDropdown?.classList.remove("is-open");
        return;
      }

      switch (action) {
        case "bold":
          editor.chain().focus().toggleBold().run();
          break;
        case "italic":
          editor.chain().focus().toggleItalic().run();
          break;
        case "strike":
          editor.chain().focus().toggleStrike().run();
          break;
        case "p":
          editor.chain().focus().setParagraph().run();
          break;
        case "bulletList":
          editor.chain().focus().toggleBulletList().run();
          break;
        case "orderedList":
          editor.chain().focus().toggleOrderedList().run();
          break;
        case "taskList":
          editor.chain().focus().toggleTaskList().run();
          break;
        case "alignLeft":
          editor.chain().focus().setTextAlign("left").run();
          break;
        case "alignCenter":
          editor.chain().focus().setTextAlign("center").run();
          break;
        case "alignRight":
          editor.chain().focus().setTextAlign("right").run();
          break;
        case "blockquote":
          editor.chain().focus().toggleBlockquote().run();
          break;
        case "code":
          editor.chain().focus().toggleCode().run();
          break;
        case "hr":
          editor.chain().focus().setHorizontalRule().run();
          break;
        case "undo":
          editor.chain().focus().undo().run();
          break;
        case "redo":
          editor.chain().focus().redo().run();
          break;
        case "link": {
          const url = window.prompt("URL");
          if (url)
            editor
              .chain()
              .focus()
              .extendMarkRange("link")
              .setLink({ href: url })
              .run();
          else if (url === "")
            editor.chain().focus().extendMarkRange("link").unsetLink().run();
          break;
        }
        case "color": {
          const color = window.prompt(
            "Color (e.g., #ff0000 or red)",
            "#000000",
          );
          if (color) editor.chain().focus().setColor(color).run();
          break;
        }
        case "image":
        case "video": {
          const input = document.createElement("input");
          input.type = "file";
          input.accept = `${action}/*`;
          input.multiple = true;
          input.onchange = ({ target }) => {
            if (target.files?.length) {
              Array.from(target.files).forEach((file) =>
                uploadAndInsertMedia(file, action, editor.view),
              );
            }
          };
          input.click();
          break;
        }
      }
    });
  });

  function setupCoverImagePicker() {
    const titleAnchor = document.getElementById("post-title");
    if (!titleAnchor) return;

    const picker = document.createElement("div");
    picker.id = "cover-image-picker";
    picker.innerHTML = `
      <input type="hidden" id="post-cover-image">
      <input type="file" id="cover-image-input" accept="image/*">
      <div id="cover-image-drop-zone">
        <div id="cover-image-placeholder">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">
            <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
            <circle cx="8.5" cy="8.5" r="1.5"></circle>
            <polyline points="21 15 16 10 5 21"></polyline>
          </svg>
          <span>Add a cover image</span>
        </div>
        <img id="cover-image-preview" alt="Cover image preview">
      </div>
      <div id="cover-image-actions">
        <button class="cover-image-action-btn" id="cover-image-change-btn">Change</button>
        <button class="cover-image-action-btn" id="cover-image-remove-btn">Remove</button>
      </div>
    `;
    titleAnchor.parentNode.insertBefore(picker, titleAnchor);

    const dropZone = picker.querySelector("#cover-image-drop-zone");
    const fileInput = picker.querySelector("#cover-image-input");
    const preview = picker.querySelector("#cover-image-preview");
    const hiddenInput = picker.querySelector("#post-cover-image");
    const actions = picker.querySelector("#cover-image-actions");
    const changeBtn = picker.querySelector("#cover-image-change-btn");
    const removeBtn = picker.querySelector("#cover-image-remove-btn");

    function activateCoverImageDisplay() {
      dropZone.classList.add("has-image");
      actions.style.display = "flex";
    }

    async function handleFile(file) {
      if (!file || !file.type.startsWith("image/")) return;
      const base64 = await fileToBase64(file);
      preview.src = base64;
      activateCoverImageDisplay();
      try {
        const result = await frappeClient.uploadFile(file, {
          doctype: "Cafe Post",
          docname: postId || "new-post",
          fieldname: "cover_image",
        });
        hiddenInput.value = result.file_url;
        preview.src = result.file_url;
      } catch {
        hiddenInput.value = base64;
      }
    }

    function setCoverImage(url) {
      if (!url) return;
      hiddenInput.value = url;
      preview.src = url;
      activateCoverImageDisplay();
    }

    window._setCoverImage = setCoverImage;

    dropZone.addEventListener("click", () => fileInput.click());
    changeBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      fileInput.click();
    });
    removeBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      hiddenInput.value = "";
      preview.src = "";
      dropZone.classList.remove("has-image");
      actions.style.display = "none";
      fileInput.value = "";
    });

    fileInput.addEventListener("change", () => {
      if (fileInput.files?.[0]) handleFile(fileInput.files[0]);
    });

    dropZone.addEventListener("dragover", (e) => {
      e.preventDefault();
      dropZone.classList.add("drag-over");
    });
    dropZone.addEventListener("dragleave", () =>
      dropZone.classList.remove("drag-over"),
    );
    dropZone.addEventListener("drop", (e) => {
      e.preventDefault();
      dropZone.classList.remove("drag-over");
      const file = e.dataTransfer?.files?.[0];
      if (file) handleFile(file);
    });
  }

  setupCoverImagePicker();

  function resizeHeight(el) {
    if (!el || !el.scrollHeight) return;
    el.style.height = "auto";
    el.style.height = el.scrollHeight + "px";
  }

  function attachAutoResize(el) {
    if (!el) return;
    el.addEventListener("input", () => resizeHeight(el));
    resizeHeight(el);
  }

  const descEl = document.getElementById("post-description");

  if (descEl) {
    descEl.maxLength = 250;
    attachAutoResize(descEl);
    descEl.addEventListener("keydown", (e) => {
      if (e.key === "Enter") e.preventDefault();
    });
  }

  const titleEl = document.getElementById("post-title");

  if (titleEl) {
    titleEl.maxLength = 60;
    attachAutoResize(titleEl);
    titleEl.addEventListener("keydown", (e) => {
      if (e.key === "Enter") e.preventDefault();
    });
  }

  const pageTitleTag = document.querySelector("title");

  if (!isNewPost) {
    frappeClient
      .getDoc("Cafe Post", postId)
      .then(({ data: post }) => {
        editor.commands.setContent(withBottomSpace(post.content));
        if (titleEl) titleEl.value = post.title || "";
        resizeHeight(titleEl);

        if (pageTitleTag) {
          pageTitleTag.textContent = `Editing - ${post.title}`;
        }

        if (descEl) {
          descEl.value = post.description || "";
          resizeHeight(descEl);
        }

        if (post.cover_image) {
          window._setCoverImage?.(post.cover_image);
        }

        if (post.tags && post.tags.length > 0) {
          window._addPreloadedTags?.(post.tags.map((t) => t.tag));
        }
      })
      .catch((err) => console.error("Failed to load post:", err));
  } else {
    if (pageTitleTag) {
      pageTitleTag.textContent = "Create New Post";
    }
  }

  const navbarActionButtons = document.getElementById("navbar-action-buttons");
  if (navbarActionButtons) {
    navbarActionButtons.innerHTML = "";
    const publishBtn = document.createElement("button");
    publishBtn.id = "publish-post";
    publishBtn.textContent = "Publish";
    publishBtn.style.cssText =
      "background-color: #1a1a1a; color: #ffffff; border: none; border-radius: 8px; padding: 4px 10px; font-size: 13px;";

    function resetPublishBtn() {
      publishBtn.textContent = "Publish";
      publishBtn.disabled = false;
    }

    publishBtn.addEventListener("click", async (e) => {
      e.preventDefault();
      publishBtn.disabled = true;
      publishBtn.textContent = "Publishing…";
      try {
        const coverEl =
          document.getElementById("post-cover-image") ||
          document.querySelector(
            "input[name='cover_image'], input[data-field='cover_image']",
          );

        if (!titleEl?.value?.trim()) {
          toast.warning("Please add a title");
          resetPublishBtn();
          return;
        }
        if (!descEl?.value?.trim()) {
          toast.warning("Please add a description");
          resetPublishBtn();
          return;
        }

        const contentText = editor.getText();
        const wordCount = contentText
          .trim()
          .split(/\s+/)
          .filter(Boolean).length;
        if (wordCount < 400) {
          toast.warning(
            `Post content must be at least 400 words, current count is ${wordCount}.`,
          );
          resetPublishBtn();
          return;
        }

        const values = {
          title: titleEl?.value || "",
          description: descEl?.value || "",
          cover_image: coverEl?.value || "",
          content: stripTrailingEmptyParagraphs(editor.getHTML()),
          published: 1,
          tags: (window.getSelectedTags?.() || []).map((tag) => ({ tag })),
        };

        if (isNewPost) {
          const { data: created } = await frappeClient.post(
            "Cafe Post",
            values,
          );
          window.location.href = `/cafe/posts/${encodeURIComponent(created.slug)}`;
        } else {
          publishBtn.textContent = "Saving…";
          const postData = await frappeClient.update(
            "Cafe Post",
            postId,
            values,
          );
          publishBtn.textContent = "Published";
          window.location.href = `/cafe/posts/${postData.data.slug}`;
        }
      } catch (err) {
        console.error("Publish failed:", err);
        toast.error(`Publish failed: ${err.message}`);
        resetPublishBtn();
      }
    });
    navbarActionButtons.appendChild(publishBtn);
  }

  const tagsContainer =
    document.querySelector("#tags-container") ||
    document.querySelector(".tags-container");
  if (tagsContainer) {
    const selectedTags = new Set();

    const inputWrapper = document.createElement("div");
    inputWrapper.className = "tag-input-wrapper";

    const input = document.createElement("input");
    input.type = "text";
    input.className = "tag-search-input";
    input.placeholder = "Add tags…";
    input.style.padding = 0;

    const dropdown = document.createElement("div");
    dropdown.className = "tag-dropdown";

    inputWrapper.appendChild(input);
    inputWrapper.appendChild(dropdown);
    tagsContainer.appendChild(inputWrapper);

    function renderChips() {
      tagsContainer.querySelectorAll(".tag-chip").forEach((el) => el.remove());
      selectedTags.forEach((name) => {
        const chip = document.createElement("span");
        chip.className = "tag-chip";
        chip.innerHTML = `${name}<span class="tag-remove" data-tag="${name}">×</span>`;
        tagsContainer.insertBefore(chip, inputWrapper);
      });
    }

    function renderDropdown(query) {
      const tags = (window.page_data && window.page_data.tags) || [];
      const filtered = tags
        .map((t) => t.name)
        .filter(
          (n) =>
            !selectedTags.has(n) &&
            n.toLowerCase().includes(query.toLowerCase()),
        );

      dropdown.innerHTML = "";
      if (filtered.length === 0) {
        const opt = document.createElement("div");
        opt.className = "tag-option no-results";
        opt.textContent = "No tags found";
        dropdown.appendChild(opt);
      } else {
        filtered.forEach((name) => {
          const opt = document.createElement("div");
          opt.className = "tag-option";
          opt.textContent = name;
          opt.addEventListener("mousedown", (e) => {
            e.preventDefault();
            if (selectedTags.size >= 3) return;
            selectedTags.add(name);
            input.value = "";
            renderChips();
            renderDropdown(input.value);
            if (selectedTags.size >= 3) {
              dropdown.classList.remove("is-open");
              input.placeholder = "";
              input.disabled = true;
            }
          });
          dropdown.appendChild(opt);
        });
      }
    }

    input.addEventListener("focus", () => {
      renderDropdown(input.value);
      dropdown.classList.add("is-open");
    });

    input.addEventListener("input", () => {
      renderDropdown(input.value);
      dropdown.classList.add("is-open");
    });

    input.addEventListener("blur", () => {
      setTimeout(() => dropdown.classList.remove("is-open"), 150);
    });

    tagsContainer.addEventListener("click", (e) => {
      if (e.target.classList.contains("tag-remove")) {
        selectedTags.delete(e.target.dataset.tag);
        input.disabled = false;
        input.placeholder = "Add tags…";
        renderChips();
      }
    });

    window.getSelectedTags = () => Array.from(selectedTags);

    window._addPreloadedTags = (tags) => {
      tags.forEach((name) => {
        if (selectedTags.size < 3) selectedTags.add(name);
      });
      renderChips();
      if (selectedTags.size >= 3) {
        input.disabled = true;
        input.placeholder = "";
      }
    };
  }
}

